from dataclasses import dataclass,field

@dataclass
class PaymentService:
    balance:int=0
    seen:dict=field(default_factory=dict)
    def charge(self,key,amount):
        fingerprint=(amount,)
        if key in self.seen:
            if self.seen[key][0]!=fingerprint: raise ValueError("key reused with different payload")
            return self.seen[key][1]
        self.balance+=amount;response={"status":"charged","balance":self.balance}
        self.seen[key]=(fingerprint,response)
        return response

s=PaymentService();print(s.charge("req-123",50));print(s.charge("req-123",50));print("final balance",s.balance)
try:s.charge("req-123",70)
except ValueError as e:print("rejected:",e)
